package local.morph.iptvcheck;
import android.app.*;import android.os.*;import android.content.*;import java.io.*;import java.net.*;import java.lang.reflect.*;import java.util.*;import java.util.concurrent.*;import java.util.zip.*;import org.json.*;
/** Actual Android JSON reader, HTTP transport, native catalogs and library search. No user account changes. */
public class CatalogInstrumentation extends Instrumentation {
 static final int COUNT=6200;ServerSocket server;ExecutorService workers=Executors.newCachedThreadPool();volatile boolean stop;Object store;
 void check(boolean ok,String why){if(!ok)throw new AssertionError(why);}
 Object call(Object target,String name,Class<?>[] types,Object... args)throws Exception{Method m=target.getClass().getDeclaredMethod(name,types);m.setAccessible(true);try{return m.invoke(target,args);}catch(InvocationTargetException e){Throwable t=e.getCause();if(t instanceof Exception)throw (Exception)t;throw e;}}
 Object client(String path)throws Exception{Class<?> c=Class.forName("local.tvmorph.tv.Xtream",true,getTargetContext().getClassLoader());Constructor<?> ctor=c.getDeclaredConstructor(JSONObject.class);ctor.setAccessible(true);return ctor.newInstance(new JSONObject().put("server","http://127.0.0.1:"+server.getLocalPort()+path).put("username","owned-fixture").put("password","owned-fixture").put("profileId",UUID.randomUUID().toString()));}
 JSONArray list(Object x,String kind)throws Exception{return (JSONArray)call(x,"list",new Class[]{String.class,String.class},kind,"");}
 void serve(Socket socket){try(Socket s=socket){BufferedReader header=new BufferedReader(new InputStreamReader(s.getInputStream(),"UTF-8"));String path=header.readLine();while(true){String line=header.readLine();if(line==null||line.isEmpty())break;}boolean gzip=path.contains("/gzip/"),broken=path.contains("/broken/"),series=path.contains("action=get_series"),empty=path.contains("/empty/");OutputStream raw=s.getOutputStream();raw.write(("HTTP/1.1 200 OK\r\nContent-Type: application/json; charset=utf-8\r\nConnection: close\r\n"+(gzip?"Content-Encoding: gzip\r\n":"")+"\r\n").getBytes("UTF-8"));OutputStream stream=gzip?new GZIPOutputStream(raw,32768):raw;BufferedWriter out=new BufferedWriter(new OutputStreamWriter(stream,"UTF-8"),65536);out.write('[');char[] padding=new char[4600];Arrays.fill(padding,'x');for(int i=1;!empty&&i<=COUNT;i++){if(i>1)out.write(',');out.write("{\""+(series?"series_id":"stream_id")+"\":\""+i+"\",\"name\":\""+(i==COUNT?"Last Library Needle":"Title "+i)+"\",\"category_id\":\""+(i%3)+"\",\"rating\":\"8.4\",\"year\":\"2025\",\"container_extension\":\"mkv\",\"plot\":\"");out.write(padding);out.write("\",\"backdrop_path\":[\"http://owned.test/art.jpg\"],\"unused\":{\"nested\":[1,{\"quoted\":\"brace } [ escaped \\\"\"}]}}");}if(!broken)out.write(']');out.flush();if(gzip)((GZIPOutputStream)stream).finish();}catch(Exception ignored){}}
 @Override public void onCreate(Bundle b){super.onCreate(b);start();}
 @Override public void onStart(){Bundle result=new Bundle();try{server=new ServerSocket(0,8,InetAddress.getByName("127.0.0.1"));workers.execute(()->{while(!stop)try{Socket s=server.accept();workers.execute(()->serve(s));}catch(Exception ignored){}});
  Object x=client("");boolean oldFailed=false;try{call(x,"networkRequest",new Class[]{String.class,String.class,String.class},"get_vod_streams",null,null);}catch(IOException expected){oldFailed=expected.getMessage().contains("too large");}check(oldFailed,"Fixture must exceed the previous 24 MiB whole-response path");
  JSONArray movies=list(x,"vod");check(movies.length()==COUNT,"Movie catalog truncated");JSONObject last=movies.getJSONObject(COUNT-1);check(last.getString("id").equals(""+COUNT)&&last.getString("name").equals("Last Library Needle"),"Last movie missing");check(last.getString("ext").equals("mkv")&&last.getString("year").equals("2025")&&last.getString("rating").equals("8.4")&&!last.has("plot"),"Normalized fields lost or unused plot retained");movies=null;
  JSONObject preview=(JSONObject)call(x,"preview",new Class[]{String.class,String.class,int.class},"vod","",8);check(preview.getJSONArray("rows").length()==8&&!preview.getBoolean("totalExact")&&preview.getBoolean("hasMore"),"Home preview must stop at eight rows without reading the whole catalog");
  ClassLoader loader=getTargetContext().getClassLoader();Class<?> reader=Class.forName("local.tvmorph.tv.ProviderCatalog",true,loader),rowType=Class.forName("local.tvmorph.tv.ProviderCatalog$Row",true,loader);StringBuilder json=new StringBuilder("[");for(int i=0;i<2000;i++){if(i>0)json.append(",");json.append("{\"stream_id\":\"").append(i).append("\",\"name\":\"Title ").append(i).append("\",\"plot\":\"");for(int n=0;n<500;n++)json.append("x");json.append("\"}");}json.append("]");byte[] raw=json.toString().getBytes("UTF-8");final long[] consumed={0};InputStream counted=new FilterInputStream(new ByteArrayInputStream(raw)){@Override public int read(byte[] b,int off,int len)throws IOException{int n=in.read(b,off,len);if(n>0)consumed[0]+=n;return n;}@Override public int read()throws IOException{int n=in.read();if(n>=0)consumed[0]++;return n;}};Object mapper=java.lang.reflect.Proxy.newProxyInstance(loader,new Class[]{rowType},(proxy,method,args)->args[0]);Method read=reader.getDeclaredMethod("read",InputStream.class,int.class,rowType);read.setAccessible(true);Object partial=read.invoke(null,counted,8,mapper);Field rf=partial.getClass().getDeclaredField("rows");rf.setAccessible(true);check(((JSONArray)rf.get(partial)).length()==8&&consumed[0]<32768,"Preview read beyond its bounded prefix: "+consumed[0]+" / "+raw.length);
  Context context=getTargetContext();check(context.checkCallingOrSelfPermission("android.permission.CHANGE_WIFI_MULTICAST_STATE")==android.content.pm.PackageManager.PERMISSION_GRANTED,"Standalone multicast permission missing");android.net.wifi.WifiManager wifi=(android.net.wifi.WifiManager)context.getApplicationContext().getSystemService(Context.WIFI_SERVICE);if(wifi!=null){android.net.wifi.WifiManager.MulticastLock lock=wifi.createMulticastLock("morph-cast-permission-check");lock.acquire();check(lock.isHeld(),"Cast multicast lock acquisition failed");lock.release();}
  Class<?> type=Class.forName("local.tvmorph.tv.IptvStore",true,getTargetContext().getClassLoader());Constructor<?> ctor=type.getDeclaredConstructor(Context.class);ctor.setAccessible(true);store=ctor.newInstance(getTargetContext());Field cf=type.getDeclaredField("client");cf.setAccessible(true);cf.set(store,x);
  JSONObject page=(JSONObject)call(store,"list",new Class[]{JSONObject.class},new JSONObject().put("kind","vod").put("page",103).put("order","provider"));check(page.getInt("total")==COUNT&&page.getJSONArray("items").length()==20&&!page.getBoolean("hasMore"),"Full library pagination lost tail");
  JSONObject found=(JSONObject)call(store,"list",new Class[]{JSONObject.class},new JSONObject().put("kind","vod").put("category","1").put("search","Last Library Needle"));check(found.getInt("total")==1&&found.getJSONArray("items").getJSONObject(0).getString("id").equals(""+COUNT),"Global search cannot reach the last title");
  JSONArray series=list(client("/gzip"),"series");check(series.length()==COUNT&&series.getJSONObject(COUNT-1).getString("kind").equals("series"),"Large gzip series catalog failed");
  check(list(client("/empty"),"vod").length()==0,"Empty valid list rejected");boolean rejected=false;try{list(client("/broken"),"vod");}catch(IOException expected){rejected=true;}check(rejected,"Truncated JSON must fail without exposing partial results");
  result.putString("stream","PASS: actual Android transport and JsonReader; >28 MiB movies and gzip series, all 6200 titles, final-page pagination, last-title global search, bounded preview reads <32 KiB; cast multicast permission and lock acquisition, empty list and truncated-response rejection. No saved account modified.");finish(Activity.RESULT_OK,result);
 }catch(Throwable e){result.putString("stream","FAIL: "+e);finish(Activity.RESULT_CANCELED,result);}finally{stop=true;try{if(server!=null)server.close();if(store!=null){Field f=store.getClass().getDeclaredField("updater");f.setAccessible(true);((ExecutorService)f.get(store)).shutdownNow();}}catch(Exception ignored){}workers.shutdownNow();}}
}
